import { Resolver } from 'node:dns/promises';
import type { LookupAddress } from 'node:dns';
import { request, type RequestOptions } from 'node:https';
import { BlockList, isIP } from 'node:net';
import type { IncomingHttpHeaders } from 'node:http';
import { Readable } from 'node:stream';
import sharp from 'sharp';
import { legacyCatalogArtworkUrl } from './adminCatalogArtworkSource';
import { createCoverArtVariantScheduler, scheduleCoverArtVariant, type CoverArtVariantScheduler } from '../../services/image/coverArtVariantScheduler';

const maximumBytes = 10 * 1024 * 1024;
const maximumPixels = 16_000_000;
const deadlineMs = 8000;
const maximumRedirects = 3;
const applicationUserAgent = 'Finitude/1.0 (administrator artwork preview; https://kashewt.com)';
// The regular media pool is broader: legacy downloads retain their own small process budget.
const legacyScheduler = createCoverArtVariantScheduler(2, 2, 16, 8);
const blocked = new BlockList();
for (const [address, prefix] of [
    ['0.0.0.0', 8], ['10.0.0.0', 8], ['100.64.0.0', 10], ['127.0.0.0', 8],
    ['169.254.0.0', 16], ['172.16.0.0', 12], ['192.0.0.0', 24], ['192.0.2.0', 24],
    ['192.88.99.0', 24], ['192.168.0.0', 16], ['198.18.0.0', 15], ['198.51.100.0', 24],
    ['203.0.113.0', 24], ['224.0.0.0', 4], ['240.0.0.0', 4]
] as const) blocked.addSubnet(address, prefix, 'ipv4');
for (const [address, prefix] of [
    ['2001::', 23], ['2001:db8::', 32], ['2002::', 16], ['3ffe::', 16], ['3fff::', 20]
] as const) blocked.addSubnet(address, prefix, 'ipv6');
const globalIpv6 = new BlockList();
globalIpv6.addSubnet('2000::', 3, 'ipv6');

/** Every DNS answer must be ordinary public unicast, including answers not selected for the socket. */
export const isPublicArtworkAddress = ({ address, family }: LookupAddress) => {
    if (isIP(address) !== family || (family !== 4 && family !== 6)) return false;
    if (family === 4) return !blocked.check(address, 'ipv4');
    return globalIpv6.check(address, 'ipv6') && !blocked.check(address, 'ipv6');
};

type ArtworkResponse = { statusCode: number; headers: IncomingHttpHeaders; rawHeaders?: string[]; body: Readable };
export interface LegacyArtworkDependencies {
    lookup?: (hostname: string, signal: AbortSignal) => Promise<LookupAddress[]>;
    request?: (url: URL, address: LookupAddress, signal: AbortSignal) => Promise<ArtworkResponse>;
    httpsRequest?: typeof request;
    schedule?: CoverArtVariantScheduler;
    clientKey?: string;
    transform?: (input: Buffer, contentType: string, signal: AbortSignal, timeoutSeconds: number) => Promise<Buffer>;
    /** Tests can shorten the shared DNS, response-body and raster-decoding deadline. */
    deadlineMs?: number;
}
const unavailable = () => new Error('ADMIN_CATALOG_ARTWORK_UNAVAILABLE');
const abortable = <T>(work: Promise<T>, signal: AbortSignal) => new Promise<T>((resolve, reject) => {
    const abort = () => reject(unavailable());
    signal.addEventListener('abort', abort, { once: true });
    work.then(resolve, reject).finally(() => signal.removeEventListener('abort', abort)).catch(() => undefined);
    if (signal.aborted) abort();
});

/** Pins a previously validated DNS answer while TLS still verifies the original hostname. */
const requestPinnedArtwork = (url: URL, address: LookupAddress, signal: AbortSignal, requestFactory = request): Promise<ArtworkResponse> =>
    new Promise((resolve, reject) => {
        const options: RequestOptions & { autoSelectFamily: boolean } = {
            method: 'GET', signal, agent: false, family: address.family, autoSelectFamily: false,
            servername: url.hostname, rejectUnauthorized: true, maxHeaderSize: 8192,
            headers: { Accept: 'image/jpeg, image/png, image/webp, image/gif', 'Accept-Encoding': 'identity', 'User-Agent': applicationUserAgent },
            lookup: (_hostname, options, callback) => {
                // Node's lookup contract can request either one answer or an array.
                if (typeof options === 'object' && options.all) callback(null, [address]);
                else callback(null, address.address, address.family);
            }
        };
        const outgoing = requestFactory(url, options, response => resolve({ statusCode: response.statusCode ?? 0,
            headers: response.headers, rawHeaders: response.rawHeaders, body: response }));
        outgoing.once('error', () => reject(unavailable()));
        outgoing.end();
    });

const boundedBody = async (response: ArtworkResponse, signal: AbortSignal) => {
    if (signal.aborted) { response.body.destroy(); throw unavailable(); }
    const declared = response.headers['content-length'];
    if (declared !== undefined && (typeof declared !== 'string' || !/^\d+$/.test(declared)
        || !Number.isSafeInteger(Number(declared)) || Number(declared) <= 0 || Number(declared) > maximumBytes)) {
        response.body.destroy(); throw unavailable();
    }
    const chunks: Buffer[] = []; let bytes = 0;
    const abort = () => response.body.destroy(unavailable());
    signal.addEventListener('abort', abort, { once: true });
    if (signal.aborted) abort();
    try {
        for await (const chunk of response.body) {
            signal.throwIfAborted();
            const buffer = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
            bytes += buffer.length;
            if (bytes > maximumBytes) { response.body.destroy(); throw unavailable(); }
            chunks.push(buffer);
        }
        if (!bytes || (declared !== undefined && bytes !== Number(declared))) throw unavailable();
        return Buffer.concat(chunks, bytes);
    } finally { signal.removeEventListener('abort', abort); }
};

/** Node can discard duplicate Location headers, so inspect the raw field count before following one. */
const nextArtworkUrl = (response: ArtworkResponse, current: URL): URL | null => {
    const location = response.headers.location;
    if (typeof location !== 'string' || !location || location.length > 2048 || /[\u0000-\u0020\u007f\\]/.test(location)) return null;
    if (response.rawHeaders) {
        if (!Array.isArray(response.rawHeaders) || response.rawHeaders.length % 2) return null;
        const locations: string[] = [];
        for (let index = 0; index < response.rawHeaders.length; index += 2) {
            const name = response.rawHeaders[index], value = response.rawHeaders[index + 1];
            if (typeof name !== 'string' || typeof value !== 'string') return null;
            if (name.toLowerCase() === 'location') locations.push(value);
        }
        if (locations.length !== 1 || locations[0] !== location) return null;
    }
    try { return legacyCatalogArtworkUrl(new URL(location, current).href); }
    catch { return null; }
};

/** A per-request resolver can cancel both DNS queries instead of accumulating uncancellable lookups. */
const lookupArtworkAddresses = async (hostname: string, signal: AbortSignal): Promise<LookupAddress[]> => {
    signal.throwIfAborted();
    const resolver = new Resolver({ timeout: 2000, tries: 1 });
    const abort = () => resolver.cancel();
    signal.addEventListener('abort', abort, { once: true });
    try {
        const answers = await Promise.allSettled([resolver.resolve4(hostname), resolver.resolve6(hostname)]);
        signal.throwIfAborted();
        const addresses: LookupAddress[] = [];
        for (let index = 0; index < answers.length; index++) {
            const answer = answers[index];
            if (answer.status === 'fulfilled') addresses.push(...answer.value.map(address => ({ address, family: index ? 6 : 4 })));
            else if (!['ENODATA', 'ENOTFOUND'].includes(String(answer.reason?.code))) throw unavailable();
        }
        return addresses;
    } finally { signal.removeEventListener('abort', abort); resolver.cancel(); }
};

/** Holds the actual native promise until it settles; a destroyed stream alone does not cancel libvips. */
const transformLegacyArtwork = async (input: Buffer, contentType: string, signal: AbortSignal, timeoutSeconds: number) => {
    const image = sharp(input, { failOn: 'error', limitInputPixels: maximumPixels }).timeout({ seconds: timeoutSeconds });
    const abort = () => image.destroy();
    signal.addEventListener('abort', abort, { once: true });
    try {
        const metadata = await image.metadata();
        const expectedFormat = contentType === 'image/jpeg' ? 'jpeg' : contentType.slice(6);
        if (metadata.format !== expectedFormat || (metadata.pages ?? 1) > 1) throw unavailable();
        signal.throwIfAborted();
        // Keep the native-work lease until Sharp actually settles, even after an abort.
        const output = await image.rotate().resize(1280, 1280, { fit: 'inside', withoutEnlargement: true })
            .webp({ quality: 85, effort: 4 }).toBuffer();
        signal.throwIfAborted();
        if (!output.length || output.length > maximumBytes) throw unavailable();
        return output;
    } finally { signal.removeEventListener('abort', abort); image.destroy(); }
};

/** Every bounded redirect repeats the same DNS/TLS checks without forwarding account credentials. */
export const loadLegacyCatalogArtwork = async (
    reference: string, parentSignal: AbortSignal, dependencies: LegacyArtworkDependencies = {}
): Promise<Buffer> => {
    const url = legacyCatalogArtworkUrl(reference);
    if (!url) throw unavailable();
    const signal = AbortSignal.any([parentSignal, AbortSignal.timeout(dependencies.deadlineMs ?? deadlineMs)]);
    const deadline = Date.now() + (dependencies.deadlineMs ?? deadlineMs);
    signal.throwIfAborted();
    const clientKey = dependencies.clientKey ?? 'unknown';
    const scheduled = (dependencies.schedule ?? legacyScheduler)(clientKey, signal, async () => {
        let target = url;
        const visited = new Set([target.href]);
        for (let redirects = 0; redirects <= maximumRedirects; redirects++) {
            signal.throwIfAborted();
            const addresses = await abortable((dependencies.lookup ?? lookupArtworkAddresses)(target.hostname, signal), signal);
            if (!addresses.length || addresses.length > 32 || !addresses.every(isPublicArtworkAddress)) throw unavailable();
            const response = await abortable((dependencies.request ?? ((target, address, signal) =>
                requestPinnedArtwork(target, address, signal, dependencies.httpsRequest)))(target, addresses[0], signal), signal);
            if ([301, 302, 303, 307, 308].includes(response.statusCode)) {
                response.body.destroy();
                const next = nextArtworkUrl(response, target);
                if (redirects === maximumRedirects || !next || visited.has(next.href)) throw unavailable();
                visited.add(next.href); target = next; continue;
            }
            const contentType = String(response.headers['content-type'] ?? '').split(';')[0].trim().toLowerCase();
            if (response.statusCode !== 200 || !['image/jpeg', 'image/png', 'image/webp', 'image/gif'].includes(contentType)
                || (response.headers['content-encoding'] && response.headers['content-encoding'] !== 'identity')) {
                response.body.destroy(); throw unavailable();
            }
            const input = await abortable(boundedBody(response, signal), signal);
            signal.throwIfAborted();
            // The native lease is shared with public artwork and outlives an HTTP timeout if necessary.
            return scheduleCoverArtVariant(clientKey, signal, async () => {
                signal.throwIfAborted();
                const timeoutSeconds = Math.min(8, Math.max(1, Math.ceil((deadline - Date.now()) / 1000)));
                const output = await (dependencies.transform ?? transformLegacyArtwork)(input, contentType, signal, timeoutSeconds);
                signal.throwIfAborted();
                return output;
            });
        }
        throw unavailable();
    });
    // An expired response returns promptly, while both resource schedulers retain the real task lease.
    return abortable(scheduled, signal);
};

/** Stable dependency seam keeps route tests isolated from real DNS, HTTPS and private artwork. */
export const legacyCatalogArtwork = { load: loadLegacyCatalogArtwork };
